<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Retrieve;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariableRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Service\Visibility\TemplateVariableVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableReadGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVariableRetrieveUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly TemplateVariableVisibilityService $visibility,
        private readonly TemplateVariableReadGateway $reader
    ) {
    }

    public function allowRetrieve(?TemplateVariableRef $ref = null): Allow
    {
        $this->logDebug("Check allow of retrieve usecase for Template variable");
        $span = $this->startSpan("Check allow of retrieve usecase for Template variable");
        try {
            $result = $this->dispatcher->dispatch(new TemplateVariableRetrieveAllowDecision(Allow::allowed('retrieve', 'Allowed to retrieve by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function hiddenFields(?TemplateVariableRef $ref = null): array
    {
        $this->logDebug("Check hidden fields usecase for Template variable");
        $span = $this->startSpan("Check hidden fields usecase for Template variable");
        try {
            return $this->visibility->fieldsToHide($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function retrieve(string $uid): TemplateVariableRetrieveResult
    {
        $this->logDebug("Run retrieve usecase for Template variable");
        $span = $this->startSpan("Run retrieve usecase for Template variable");
        try {
            $ref = new TemplateVariableRef($uid);
            $allow = $this->allowRetrieve($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to retrieve Template variable');
            }
            if (!$result = $this->visibility->retrieveVisible($ref)) {
                throw new NotFoundException($uid);
            }
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new TemplateVariableRetrieveResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
